import java.io.*;import java.util.*;class Result {public static int powerSum(int X,int N){int maxBase=(int)Math.pow(X,1.0/N);return countWays(X,N,1,maxBase);}private static int countWays(int remaining,int N,int start,int maxBase){if(remaining==0){return 1;}int count=0;for(int i=start;i<=maxBase;i++){long p=1;for(int j=0;j<N;j++){p*=i;if(p>remaining){break;}}if(p>remaining){break;}count+=countWays((int)(remaining-p),N,i+1,maxBase);}return count;}}public class Solution{public static void main(String[] args) throws IOException{BufferedReader bufferedReader=new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter=new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH")));int X=Integer.parseInt(bufferedReader.readLine().trim());int N=Integer.parseInt(bufferedReader.readLine().trim());int result=Result.powerSum(X,N);bufferedWriter.write(String.valueOf(result));bufferedWriter.newLine();bufferedReader.close();bufferedWriter.close();}}